CREATE TABLE visitors(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,channel_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,channel_id,id),FOREIGN KEY(workspace_id,channel_id) REFERENCES channels(workspace_id,id));
CREATE TABLE conversations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,channel_id uuid NOT NULL,visitor_id uuid NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','snoozed')),reply_owner text NOT NULL DEFAULT 'HANDOFF_PENDING' CHECK(reply_owner IN ('AI_ACTIVE','HANDOFF_PENDING','HUMAN_ACTIVE')),owner_version integer NOT NULL DEFAULT 1,assigned_to uuid,next_sequence integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,channel_id,visitor_id) REFERENCES visitors(workspace_id,channel_id,id),FOREIGN KEY(workspace_id,assigned_to) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE messages(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,conversation_id uuid NOT NULL,client_id uuid NOT NULL,sequence integer NOT NULL,author_type text NOT NULL CHECK(author_type IN ('visitor','agent','ai')),actor_id uuid REFERENCES users(id),visibility text NOT NULL CHECK(visibility IN ('public','internal')),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 10000),visitor_received_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,conversation_id,client_id),UNIQUE(workspace_id,conversation_id,sequence),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id),CHECK(visibility<>'internal' OR author_type='agent'));
ALTER TABLE visitors ENABLE ROW LEVEL SECURITY;ALTER TABLE visitors FORCE ROW LEVEL SECURITY;
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;ALTER TABLE conversations FORCE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;ALTER TABLE messages FORCE ROW LEVEL SECURITY;
CREATE POLICY visitors_scope ON visitors USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid) WITH CHECK(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid);
CREATE POLICY conversations_scope ON conversations USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid) WITH CHECK(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid);
CREATE POLICY messages_scope ON messages USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid) WITH CHECK(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE ON visitors,conversations,messages TO gotek_app;
